// Discord-бот PANDAMIA: модерация голосовых каналов (права владельцев, мут/глухота,
// тег 🔑), бан-таймаут за выход с сервера, музыка и мост между серверами (pipe).
// Всё, что зависит от конкретного сервера, -- в config.json (шаблон: config.example.json).
// node >= 22 (портативный: ./node-v24.21.0-win-x64/node.exe)
// discord.js v14:
//   npm install discord.js @keyv/sqlite keyv
// CHANGELOG v2 (переход на discord.js v14 / keyv v5 / node 24):
//   * intents строками (v13-стиль) + partials: ['Channel'] (иначе ЛС не работают)
//   * keyv v5: const { Keyv } = require('keyv');
//   * channel.type: enum ChannelType (0 = GUILD_TEXT, 1 = DM)
//   * permissionOverwrites: overwrite.allow/deny -- PermissionsBitField (не Collection)
//   * displayAvatarURL: { extension: 'png', forceStatic: false, size: 1024 }
//   * users.fetch: один аргумент (опции cache/force убраны в v14)
//   * user.tag -- null (только username, без discriminator), uu()/uuu() без '#0'
//   * setBitrate: число bps (не строка '64000')
//   * embed timestamp: только Date/number/ISO (locale-строка d() кидала 'Invalid time value')
//   * color 'BLUE' (v13-стиль, капсом) НЕ распознаётся EmbedBuilder -> 'Blue'/hex
//   * channelCreate/channelUpdate: в v14 каналы приходят без guild -> берём через .guild ?? client.guilds.cache.get
//   * [FIX v2] NaN-баг в логе переименования: скобки вокруг 'Владельцы канала: ' + (owners.size ? ... : ...)
//   * [FIX v2] e.message там, где e не существует (users.fetch .catch(() => null))
// CHANGELOG v2.18 (бот играет там, где слушает автор трека; /announce и /dm без интентов):
//   * ПОЕХАЛИ К АВТОРУ ТРЕКА: перед стартом трека бот смотрит, в каком голосовом канале
//     сидит тот, кто этот трек добавил, и переезжает туда (если он вообще в голосовом).
//     Так каждый трек играет там, где его слушает автор; бот остаётся в этом канале до
//     трека другого автора или до /leave. Автор вне голосового -- бот не двигается.
//     Сам он по-прежнему никогда не заходит и не выходит: переезд возможен только когда
//     он уже где-то играет, и не сразу после явного /join|/play (m.justJoinedAt), чтобы
//     не уехать от человека, который только что его позвал. В логе видно причину:
//     '[music] перешёл в «X» -- автор трека Y слушает здесь'.
//     Тот же смысл и у паузы: если бот стоит ОДИН (пауза, слушателей нет), а автор
//     текущего/следующего трека зашёл в другой голосовой канал -- бот едет туда и
//     продолжает с того же места ('здесь никого, а автор трека ... слушает здесь').
//     Логика паузы/продолжения не дублируется: после переезда checkListeners
//     вызывается заново и сам снимает паузу обычным путём.
//   * /announce и /dm -- слэш-команды вместо текстовых (мост из пандалогии и `panda dm`):
//     текст и вложение приходят в самой команде, то есть интент Message Content им НЕ
//     нужен, а Discord именно это и советует вместо запроса этого интента.
//   * «Переслать в общий» -- команда-контекстное меню (правый клик по сообщению):
//     Discord отдаёт выбранное сообщение ЦЕЛИКОМ (текст + вложения) без интента
//     Message Content, поэтому это замена мосту из пандалогии, если интент отзовут.
//     Оригинал удаляется только в канале-источнике (как у моста); если staff
//     переслал сообщение из другого канала, оригинал остаётся (чужое не удаляем).
//     Отправка у моста и у меню -- ОДНА функция relayPipe (поведение не разъезжается).
//   * [/join] ЗАЩИТА ОТ ПЕРЕХВАТА: если бот играет трек, а его автр сидит в той же
//     комнате (то есть бот поёт именно для него), другой DJ не уведёт бота командой
//     /join -- отказ виден только вызвавшему, а в лог идёт 'кто просил / что играет /
//     для кого'. Если автора в комнате нет -- /join работает, но при живых слушателях
//     в ответе и в логе прямо сказано, что они остались без музыки. Без музыки и во
//     время /leave -- /join как раньше.
//   * [login] ОДНА строка при старте: в скольких серверах живёт приложение и сколько
//     людей в них суммарно ('приложение в 2 серверах, участников суммарно ~11745')
//     -- порог ревью Discord считается именно по людям всех серверов, а memberCount
//     приходит в GUILD_CREATE, то есть видно без интентов.
//   * [music] Stage-каналы: бот заходит и туда, а в лог пишется подсказка, что для
//     слышимости Stage Moderator должен сделать его спикером (Discord иначе не
//     пускает бота вещать в эфир).
// CHANGELOG v2.17 (интенты по факту, /rolecheck, руками двигать очередь):
//   * [intents] ОТЧЁТ ПРИ СТАРТЕ: что РЕАЛЬНО доступно приложению -- Message Content
//     (по интенту в гейтвее), Guild Members (события), полный список участников
//     (проверяется ФАКТОМ -- пришёл ли список) и журнал аудита (пробный запрос).
//   * [intents] Guild Members ПОДКЛЮЧЁН в гейтвее ("GUILD_MEMBERS": true в config.json):
//     вход/выход теперь мгновенные (guildMemberAdd/Remove), а опрос раз в 45 сек
//     остаётся резервным путём. Один и тот же переход они не обрабатывают дважды
//     (отметка на 5 минут -- иначе только что вошедший «выходил» бы по устаревшему
//     REST-списку и получал таймаут). Интент может быть ОТОЗВАН -- тогда login падает
//     'Used disallowed intents', бот сам снимает интент и стартует без него.
//   * [/rolecheck user:@кто] -- что бот помнит о человеке: роли (save_roles), что
//     вернёт при входе, текущее наказание с точным сроком и историю за окно.
//     Работает и для того, кто НЕ на сервере (одиночный REST-запрос без интента).
//   * [/queue] 25 треков на страницу (было 10) + защита от лимита сообщения 2000
//     символов (страница собирается по бюджету, листание идёт по показанным номерам).
//   * [/queue] КНОПКИ-СТРЕЛКИ: меню «🎚 Двигать трек» + «⬆ Выше» / «⬇ Ниже» / «✖ Готово».
//     Логика перестановки -- общая с /move (queueMove), авторство -- в логе.
//   * [welcome] в ЛС переносится ТЕКСТ и КАРТИНКА из сообщения с правилами
//     (раньше была только ссылка, а Discord рисовал её как название сервера).
//     Нужны ОБА ключа: welcome_channel -- где искать, welcome_message -- что именно
//     (поиска сообщения по id без канала в API нет).
//   * [лог] уборка старых записей больше не пишет «убрал N» -- пишет про СРОК ХРАНЕНИЯ
//     (понятно, что данные старше окна, а не что-то потерялось).
// CHANGELOG v2.16 (точные роли, кнопки под /queue, защита от пустого списка):
//   * [роли] ТОЧНОСТЬ: снимок поллера бывает до 45 секунд старым, поэтому роль,
//     снятая за секунды до выхода человека, попадала в базу и возвращалась при входе.
//     Теперь правки ролей после снимка достраиваются по журналу аудита
//     (gateway-событие MemberRoleUpdate + REST-запрос как фолбэк), а если возвращать
//     нечего -- старая запись стирается (иначе она воскрешала бы уже потерянную роль).
//   * [/queue] БЫСТРЫЕ КНОПКИ под очередью: «⏭ Пропустить», «🧹 Очистить» и меню
//     «🗑 Убрать трек» с номерами текущей страницы (те же номера, что в /remove).
//     Права -- как у слэш-команд (DJ/админ/модер); листание -- по-прежнему только
//     тем, кто открыл очередь. Логика общая со /skip, /clear, /remove (одна правка).
//   * [poll] ЗАЩИТА ОТ «ПУСТОГО» СПИСКА УЧАСТНИКОВ: если Discord вернёт пустой или
//     внезапно усохший список (403 с пустым телом, лимит, сбой), тик пропускается --
//     раньше это выглядело бы как «ВСЕ вышли» и каждому выписался бы таймаут за
//     выход (а перезаход -- бан). Плюс явная строка про интент Guild Members: без
//     него полный список недоступен и вход/выход молча перестают работать.
// CHANGELOG v2.15 (управление наказаниями, история за месяц, чистый лог событий):
//   * [/unban user:@кто reason:...] -- снять таймаут/бан вручную (админ/модер): снимается
//     и запись таймаута в базе, и бан в Discord, и отложенный таймер разбона (иначе он
//     позже написал бы «unbanned» уже после ручного снятия). Кто снял и почему -- в журнал,
//     в лог и в историю (/bans).
//   * ИСТОРИЯ НАКАЗАНИЙ (bans_history_days, по умолчанию 30 дн): /bans показывает, кто
//     сколько раз выходил с сервера, получал таймаут/бан и у кого наказание снимали.
//     Пишутся события exit/timeout/ban/unban, окно -- bans_history_days, старые записи
//     убираются свипом вместе с остальными (база не растёт бесконечно).
//   * [FIX] СПАМ В ЛОГЕ «[nick] +🔑 (sweep)» каждые 45 секунд: fetch(id) БЕЗ force
//     возвращал КЭШ (а в кэше ник старый -- discord.js без интента GuildMembers его не
//     обновляет), поэтому свип заново «ставил» уже стоящий ключ и писал ту же строку.
//     Теперь ник читается из REST (force: true) и только когда состояние неизвестно, а
//     что бот поставил сам -- помнится в памяти процесса ($nickSet).
// CHANGELOG v2.14 (по просьбам владельца: видеть наказания, помнить роли, удобная очередь):
//   * [ban] ОТЧЁТ ПРИ СТАРТЕ: сколько банов/таймаутов поднято из базы -- пишется ВСЕГДА,
//     в том числе когда наказаний нет ('поднято 0: активных банов/таймаутов нет').
//     В строке видно имя, точный срок и что это: бан или только таймаут.
//   * [/bans] -- кто сейчас в наказании: имя, бан/таймаут, срок до секунды и причина.
//     Только админ/модер, ответ виден вызвавшему, вызов команды -- в логе как обычно.
//   * ТОЧНЫЕ СРОКИ вместо «~3 мин»: и в логе, и в письме, и в причине бана в Discord
//     ('banned until 18.09.2026, 21:04:33 (left 00:03:20, re-enter during timeout)').
//   * РОЛИ МЕЖДУ ПЕРЕЗАХОДАМИ (save_roles, ВКЛ по умолчанию): на выходе роли человека
//     кладутся в базу (ключ -- id), на входе ДОБАВЛЯЮТСЯ недостающие -- ничего не
//     снимаем, поэтому это мирно сосуществует с другим ботом-хранителем ролей.
//     Не храним @everyone/роли интеграций/удалённые роли; список исключений --
//     save_roles_exclude, срок хранения -- save_roles_days (30 дн, чистится свипом).
//   * ОЧЕРЕДЬ ГЛАЗАМИ DJ: в /queue виден автор каждого трека ('· 👤 ник'), сколько
//     уже играет текущий и СКОЛЬКО ВСЕГО ждать до конца плейлиста (с учётом позиции
//     в текущем треке; эфиры и треки без длины -- отдельно); у длинных очередей --
//     кнопки «◀ Назад / Вперёд ▶» (страница зашита в customId, чужой не перелистнёт).
//     Новое: '/clear author:@кто' -- убрать из очереди треки одного человека.
//   * ВЫРАВНИВАНИЕ ГРОМКОСТИ (MUSIC.normalize, ВКЛ по умолчанию): между yt-dlp и
//     Discord становится свой ffmpeg с фильтром loudnorm, поэтому песни больше не
//     отличаются громкостью. Фильтр проверяется один раз при старте; не умеет --
//     играем как раньше (без нормализации). Отключить: MUSIC.normalize = false.
//   * [FIX] УТЕЧКА ПРОЦЕССОВ: player.stop() НЕ закрывает поток трека, поэтому после
//     /skip, /stop и /leave yt-dlp (и добавленный ffmpeg) оставались висеть в памяти.
//     Теперь у играющего трека есть streamHandle, и он глушится в Idle-обработчике.
//   * [FIX] MUSIC.proxy из config.json реально читается (раньше объект MUSIC вообще
//     не брался из конфига -- всегда работал только дефолт/переменная окружения).
//   * ПЕРЕНОС БОТА РУКАМИ (drag&drop) виден в логе и снимает статус со старого канала.
//   * КОММЕНТАРИИ В КОНФИГЕ: подсказки лежат ключами с окончанием _comment (JSON при этом
//     остаётся валидным); ключи-комментарии внутри SERVERS бот выкидывает при загрузке.
//   * КОНТАКТЫ В ПОМОЩИ: OWNER (владелец ХОСТИНГА) + owner_server (владелец сервера),
//     каждый показывается по своему флагу show_owner_hoster / show_owner_server.
//   * [panda welcome] -- посмотреть глазами новичка, какое приветствие уходит в ЛС
//     (без аргумента -- себе; другому -- только админ).
//   * лог трека -- ОДНА строка: 'играю: X (из предзагрузки, без паузы)' вместо
//     отдельной строки 'предзагрузка сыграла: X', которую читали как «прошлый отыграл».
// CHANGELOG v2.13 (приветствие новичкам + лог бан-таймаута по факту):
//   * [v2.13] ПРИВЕТ-ЛС НОВИЧКАМ ВЕРНУЛИСЬ: при входе на сервер бот пишет в личку
//     приветствие со ссылкой на сообщение из `welcome_message` (канал `welcome_channel`).
//     Нет id сообщения -- даём ссылку на канал. Пустой welcome_channel = выключено.
//     Перезаходы в таймауте приветствия НЕ получают (у них другой путь -- бан-таймаут).
//   * [v2.13] ВЕСЬ ПОТОК ТАЙМАУТА ГОВОРИТ ПРАВДУ (пункты из того же разбора):
//     -- письмо «вам ограничен вход» перезаходящему уходит ТОЛЬКО если бан действительно
//        будет выдан (onEnterBanRealy: true); если он выключен -- в лог идёт строка
//        'came back during timeout, but no ban (onEnterBanRealy is off)'; раньше письмо
//        уходило всегда (и в тексте было '[object Object]' вместо обращения к человеку,
//        потому что текст брался из сырого JSON, а не из полученного User);
//     -- запись таймаута с прошедшим сроком (= обычный вход, а не перезаход) больше
//        не выдаёт «ограничен вход» с прошедшей датой -- запись чистится, и человек
//        получает обычное приветствие;
//     -- в строке про бан видно и остаток срока: 'banned on ~3 min. (re-enter during
//        timeout, left 0:03:20)', и разбан считается от ОСТАТКА, а не от полного срока;
//     -- sweepExpiredBans сначала снимает бан и только потом чистит запись: если снятие
//        не удалось (нет прав, сеть), запись остаётся и бот попробует в следующем тике
//        (раньше запись стиралась сразу, и бот «забывал» о бане, который реально стоял).
//   * [FIX] лог бан-таймаута больше не врёт: при onLeaveBanRealy: false писалось
//     «banned on N min.», хотя бана не было -- ставился только таймаут (бан прилетает
//     при перезаходе, onEnterBanRealy). Теперь: 'timeout on N min. (ban -- only if
//     re-enters earlier)' и 'timeout expired after N min. (did not come back)'.
//     У настоящего бана в логе появились пометки '(on leave)' и '(re-enter during timeout)'.
// CHANGELOG v2.12.2 (управление длинными плейлистами + живучесть при перезапуске):
//   * [/move номер to номер] -- переставить трек в очереди (номера те же, что в
//     /queue). Ждущий продолжения трек после /leave/обрыва переставляется вместе с
//     местом в нём: seekTrack/seekSec привязаны к треку, а не к номеру, а сама позиция
//     переезжает в поле трека (track.seek) и не теряется, пока очередь до него не дойдёт.
//   * [FIX] база хранит и позицию ждущего трека (curIdx): /move 1 4 больше не
//     откатывается после перезапуска (раньше resumeMusic всегда ставил его первым).
//   * тик сохранения позиции: 20 сек -> 5 сек и ТОЛЬКО когда трек реально играет
//     (на простое и на паузе меняться нечему -- раньше писал вхолостую).
// CHANGELOG v2.12.1 (баг найден стендом при проверке памяти музыки):
//   * [FIX] БАЗА СНОВА ПИШЕТ НА ДИСК. В keyv v5 конструктор со строкой-URI больше не
//     подгружает адаптер: `new Keyv('sqlite://...')` молча уходил в стор по умолчанию
//     (Map -- ПАМЯТЬ). Всё «работало» и даже читалось обратно тем же экземпляром, но
//     на диск не попадало: бан-таймауты не переживали перезапуск, а восстанавливать
//     музыку было не из чего (после 'перезапуска' очередь оказывалась пустой).
//     Теперь адаптер передаётся явно (`store: new KeyvSqlite({uri})`), namespace -- у
//     Keyv: ключи на диске те же ('membersBanTimeout:<id>'), уже сохранённые баны целы.
//     Ошибки базы теперь видны в логе строкой '[db] <namespace>: ...' (раньше сбой
//     записи не был виден вообще).
//   * [FIX] при /leave и обрыве связи «текущий» трек попадал в базу ДВАЖДЫ (и как
//     current, и первым в tracks): после перезапуска resumeMusic склеивал его сам с
//     собой и трек играл бы ещё раз.
//   * [/leave] очередь сохраняется сразу с местом в треке, а не с нулём.
// CHANGELOG v2.12 (музыка как обещал основной пользователь: помнить всё и не бросать):
//   * очередь НЕ устаревает (было: старше 10 минут -- забываем) и не теряется ни при
//     перезапуске, ни при обрыве связи, ни по /leave. Забывает её только /stop и
//     естественный конец (доиграли живым слушателям -- строка в логе).
//   * в канале никого -- пауза (не играем в пустоту), слушатель вернулся -- продолжаем
//     с того же места; ручная /pause при этом не отменяется.
//   * обрыв потока у играющего трека -- продолжаем ТОТ ЖЕ трек с места обрыва
//     (3 попытки, потом пропуск с предупреждением в канале).
//   * после падения бот сам заходит в тот же канал, как только там появится человек
//     (после /leave -- ждёт /join). Позиция восстанавливается с точностью до секунды.
//   * /play: DJ может собирать плейлист, не находясь в голосовом канале; бот не
//     перехватывает у живого канала («кто первый, тот и прав»), а если сидит один --
//     переезжает к тому, кто позвал.
//   * управление очередью: /queue (с номерами и from:), /remove, /clear, /jump.
//   * Ctrl+C/закрытие окна сохраняют позицию сразу, а не «как успело за 20 секунд».
// CHANGELOG v2.10 (по итогам разбора живого лога):
//   * [FIX] ключ 🔑 больше не ставится повторно каждые 45 секунд: без интента GuildMembers
//     кэш ников не обновляется (setNickname правит только копию), и свип считал, что ключа
//     нет, хотя он стоял -- в логе одна и та же строка без конца, а ключ у людей появлялся
//     «после перезахода». Теперь ник меняется через setNickLogged: и на сервере, и локально.
//   * лог yt-dlp -- ОДНА строка с причиной (stderr), без команды и многострочной простыни.
//   * музыка переживает перезапуск: очередь, текущий трек и позиция -- в SQLite (musicState),
//     после старта бот возвращается в тот же канал и продолжает (с места, иначе с начала).
// CHANGELOG v2.9.1 (по итогам ревью всего кода):
//   * [FIX] предзагрузка: один поток мог получить ДВА обработчика 'error' -- одна ошибка
//     писала в лог две строки (вторая называла играющий трек «предзагрузкой»).
//   * [FIX] громкость больше не берётся из фиктивной записи $music[''] (мусор в состоянии).
//   * [FIX] запись входа/выхода в журнал: null-аватара больше не попадает в embed.
// CHANGELOG v2.5 (пересылка из пандалогии + текст команд):
//   * ИНТЕНТ Message Content теперь запрашивается (в портале приложения он ВКЛЮЧЁН).
//     Без него Discord отдаёт события без текста (content пустой) -- поэтому НЕ работали
//     ни пересылка из пандалогии в чат, ни текстовые команды 'panda ...'.
//   * Если Discord интент не даст (после 09.10.2026 без одобрения) -- бот сам
//     запустится БЕЗ него и напишет об этом в лог (деградация вместо падения).
//   * Пересылка: сперва отправка, потом удаление оригинала (иначе при ошибке
//     отправки сообщение терялось). Пустое сообщение больше НЕ удаляется.
// CHANGELOG v2.1 (работа БЕЗ привилегированных интентов -- заявку Discord подавать не надо!):
//   * [УСТАРЕЛО в v2.17] интент GuildMembers был убран (привилегированный). Оказалось,
//     что приложение И ТАК им владеет: полный список участников (REST) -- как раз та
//     возможность, которую даёт этот интент, без него опрос не работал бы. В v2.17
//     интент снова подключён как основной путь, а опрос (pollMembers) -- резервный.
//   * Welcome-ЛС новичкам были отключены на время миграции -- [v2.13] включены снова.
//   * Логи входов/выходов в журнал -- сохранены.
//   * Причины банов -- как было: 'Забанен ботом на N мин.'
//   * [БОНУС] ban-таймауты теперь рестарт-безопасны: при старте и в каждом тике
//     просроченные membersBanTimeout из SQLite снимаются (sweepExpiredBans).

const
{
    ID, TOKEN, PREFIX, SERVERS,
    ERROR, DEBUG, NOTICE, STARTUP_DM,
    MESSAGE_CONTENT,
    // [v2.17] Интент Guild Members (привилегированный): мгновенные события входа/выхода.
    // Поставь "GUILD_MEMBERS": false в config.json, если Discord его отзовёт -- тогда
    // вход/выход снова ловятся только опросом раз в 45 сек (и то, пока дают список).
    GUILD_MEMBERS,
    // [v2.14] Новые верхние ключи (все необязательные):
    //   OWNER -- id владельца ХОСТИНГА бота (кто его крутит): идёт в текст помощи
    //            как контакт «если бот выключен»; если его нет -- берётся STARTUP_DM[0].
    //   MUSIC -- настройки музыки: proxy (socks5), normalize (громкость), filter.
    OWNER, MUSIC,
}
= require ('./config.json');
const space = ' ';

// [v2.14] КОММЕНТАРИИ В КОНФИГЕ. В JSON комментариев нет, поэтому подсказки лежат
// обычными ключами с окончанием _comment (идея владельца). Читает их только человек.
// Но внутри SERVERS ключ -- это ID сервера, поэтому одноразовая чистка обязательна:
// без неё бот пытался бы работать с 'ID_СЕРВЕРА_comment' как с настоящим сервером.
// Выбрасываем всё, что не похоже на id (в том числе '_comment' и '_ПРО_КОММЕНТАРИИ').
// [v2.17] Заготовка из config.example.json ("ID_СЕРВЕРА") -- это НЕ ошибка того, кто
// только что скопировал шаблон: раньше она выглядела в логе как «странный ключ»,
// хотя человек всё сделал правильно. Теперь у неё своя понятная строка, а если
// рабочих серверов не осталось -- говорим и об этом: молча ничего не делающий бот
// хуже, чем внятная подсказка (ключ всё равно выбрасывается: с заготовкой вместо
// id бот стучался бы в несуществующий сервер).
let _srvReal = 0;
const _srvPlaceholders = [];
for (const _key of Object.keys (SERVERS))
{
    if (/^\d{17,20}$/.test (_key)) { _srvReal++; continue; }
    if (!/_comment$/.test (_key)) // '_comment' -- подсказка (молча)
    {
        if (/^ID_/.test (_key)) _srvPlaceholders.push (_key);
        else
            console.log ('[' + new Date ().toLocaleString () + '] [config] ключ "' + _key +
                '" в SERVERS -- не похож на id сервера -- пропускаю его');
    }
    delete SERVERS[_key];
}
if (_srvPlaceholders.length)
    console.log ('[' + new Date ().toLocaleString () + '] [config] в SERVERS осталась заготовка (' +
        _srvPlaceholders.join (', ') + ') -- вместо неё впиши id своего сервера ' +
        '(ПКМ по серверу -> Копировать ID, режим разработчика включён)');
if (!_srvReal)
    console.log ('[' + new Date ().toLocaleString () + '] [config] рабочих серверов нет: бот запустится, ' +
        'но делать ничего не будет -- заполни config.json (образец: config.example.json)');

// [v2.5] Привилегированный интент Message Content (в портале приложения включён).
// Он нужен двум вещам: пересылке из пандалогии и текстовым командам 'panda ...'.
// Поставь в config.json "MESSAGE_CONTENT": false -- если Discord его отзовёт.
const USE_MESSAGE_CONTENT = MESSAGE_CONTENT !== false;

// [v2.17] Привилегированный интент Guild Members (в портале приложения включён).
// Даёт ДВЕ вещи: мгновенные события GUILD_MEMBER_ADD/REMOVE (вход/выход -- без
// опроса раз в 45 сек) и полный список участников (наш поллер и так требует этот
// интент -- «без интента» он жил только потому, что приложение уже им владеет).
// Discord может забрать доступ (см. письмо от 10.09.2026, срок 09.10.2026): тогда
// вход с этим интентом падает 'Used disallowed intents' -- откатываемся автоматически.
const USE_GUILD_MEMBERS = GUILD_MEMBERS !== false;

// [v2.14] КТО В КОНТАКТАХ. Контактов теперь два, и оба необязательны:
//   * владелец ХОСТИНГА бота -- кто его запускает и следит (верхний ключ OWNER,
//     иначе первый id из STARTUP_DM, как было раньше);
//   * владелец СЕРВЕРА -- чей это сервер (ключ сервера owner_server).
// Это разные люди: бот может стоять на сервере, где владелец хостинга -- не админ.
// Показывать каждый контакт можно отдельно: show_owner_hoster / show_owner_server
// (по умолчанию включены). Зашитых id в коде нет: репозиторий отдаётся людям как есть.
const OWNER_HOSTER =
    /^\d{17,20}$/.test (String (OWNER || ''))
        ? String (OWNER)
        : ((Array.isArray (STARTUP_DM) && /^\d{17,20}$/.test (STARTUP_DM[0] || '')) ? STARTUP_DM[0] : '');

// Строка контактов для текста помощи (с учётом флагов сервера):
function contactsText (server)
{
    const s = SERVERS[server] || {};
    let list = [];
    const hoster = (s.show_owner_hoster === false) ? '' : OWNER_HOSTER;
    const owner  = (s.show_owner_server === false)
        ? ''
        : (/^\d{17,20}$/.test (String (s.owner_server || '')) ? String (s.owner_server) : '');
    if (hoster) list.push (u (hoster) + ' (хостинг бота)');
    if (owner && owner !== hoster) list.push (u (owner) + ' (владелец сервера)');
    return list.length ? list.join (', ') : 'администрации сервера';
}

// [v2.2] Инструкция по использованию. Один текст на все входы: стартовая ЛС
// (STARTUP_DM из config.json), слэш `/help` и `panda help` -- правки только здесь.
const STARTUP_DM_TEXT =
    '**Как пользоваться ботом** 🐼\n' +
    '📌 Вызвать эту инструкцию в любой момент: `/help` (видно только тебе)\n' +
    'или `panda help` (бот пришлёт её в ЛС).\n' +
    '\n' +
    '🎵 **Музыка** (слэш-команды):\n' +
    '`/play ссылка или запрос` -- трек, плейлист или прямой эфир (YouTube и др.)\n' +
    '  Добавляется В КОНЕЦ очереди. Стоять в голосовом канале не обязательно:\n' +
    '  DJ может просто собирать плейлист -- бот зайдёт, когда позовёшь.\n' +
    '`/queue` -- что играет и что дальше: номера, автор каждого трека, сколько уже\n' +
    '  играет текущий и сколько ещё ждать до конца плейлиста целиком. На странице\n' +
    '  25 треков, у длинных очередей есть кнопки «◀ Назад / Вперёд ▶» (и `from:26`).\n' +
    '  Под очередью -- быстрые кнопки: «⏭ Пропустить», «🧹 Очистить», меню\n' +
    '  «🗑 Убрать трек» и «🎚 Двигать трек» (после выбора появляются «⬆ Выше»/«⬇ Ниже»,\n' +
    '  а номер виден в списке) -- номера те же, что в `/remove`, жмёт тот, у кого права DJ\n' +
    '`/remove number` -- убрать трек, `/move number to` -- переставить его,\n' +
    '`/jump number` -- прыгнуть к треку, `/clear` -- очистить всю очередь,\n' +
    '`/clear author:@кто` -- убрать только треки этого человека\n' +
    '  (number/to -- те же номера, что в `/queue`; текущий трек в них не входит)\n' +
    '`/skip` -- следующий • `/stop` -- стоп и забыть очередь совсем\n' +
    '`/pause` / `/resume` -- пауза / продолжить\n' +
    '`/join` -- зайти в твой канал и остаться там (даже без музыки)\n' +
    '`/leave` -- выйти из канала (очередь и место помню -- продолжу по `/join`)\n' +
    'Управлять музыкой могут админы, модеры и роль DJ (смотреть очередь -- всем).\n' +
    '**Бот играет там, где слушает автор трека:** если тот, кто добавил трек, сидит\n' +
    'в голосовом канале, в момент начала этого трека бот сам переезжает к нему и\n' +
    'остаётся там до трека другого автора (или до `/leave`). Автора в голосе нет --\n' +
    'бот никуда не идёт; сам он не заходит и не выходит никогда.\n' +
    '**Бот ничего не забывает:** очередь, текущий трек и место в треке живут в базе,\n' +
    'поэтому перезапуск, обрыв связи и `/leave` музыку не сбрасывают. Если в канале\n' +
    'никого -- пауза, а когда слушатель вернётся -- продолжит с того же места.\n' +
    '\n' +
    '💬 **Команды в чате** (префикс `panda `):\n' +
    '`panda ping` -- проверка связи (ответ: pong)\n' +
    '`panda help` -- бот пришлёт эту инструкцию в ЛС\n' +
    '`panda file` + вложение -- бот вернёт файл обратно\n' +
    '`panda dm @юзер текст` -- ЛС от имени бота (только админы);\n' +
    'вместо упоминания можно указать id: `panda dm 123456789012345678 текст`\n' +
    '`panda test` -- бот напишет тебе в личку (проверка ЛС)\n' +
    '\n' +
    '🛡️ **Что бот делает сам:**\n' +
    '• мут/глухота действуют только в своём канале: в других говорить можно,\n' +
    '  вернёшься -- мут на месте; жалоба -- зайди в общий канал 🆘\n' +
    '• если в канале никого -- музыка встаёт на паузу (не играет в пустоту)\n' +
    '• выдаёт права владельцу канала и ставит тег 🔑 в ник\n' +
    '• новичку при входе приходит приветствие в личку: ТЕКСТ и картинка из\n' +
    '  сообщения с правилами (`welcome_message` в канале знакомства) плюс ссылка\n' +
    '• роли помнятся: выходя с сервера, человек не теряет свои роли -- при\n' +
    '  возврате бот вернёт их обратно (выключается `save_roles: false`)\n' +
    '• за выход с сервера ставится таймаут (в этом конфиге 20 мин): перезаход\n' +
    '  раньше срока = бан до его конца\n' +
    '• кто сейчас в наказании -- у админов и модеров есть `/bans`: имя, точный\n' +
    '  срок, причина и сводка за месяц (кто сколько раз выходил и был наказан);\n' +
    '  снять наказание досрочно -- `/unban user:@кто` (ответ виден только staff)\n' +
    '• объявление от имени бота -- `/announce text:... file:... channel:...` (staff);\n' +
    '  личное сообщение человеку -- `/dm user:@кто text:...` (админы); переслать\n' +
    '  чужое сообщение в общий канал -- правый клик по нему -> «Переслать в общий»\n' +
    '  (staff). Текст и файл берутся из самой команды, поэтому интент Message\n' +
    '  Content для всего этого не нужен\n' +
    '• что бот помнит о человеке (роли, наказания и что вернёт при входе) --\n' +
    '  `/rolecheck user:@кто`: можно проверить и того, кто не на сервере\n' +
    '\n' +
    '🧪 **Проверить на себе** (в чате, без `/`): `panda welcome` -- бот пришлёт\n' +
    'тебе такую же ЛС, что видят новички (`panda welcome @юзер` -- для другого).\n' +
    '\n' +
    '🔑 **Тег 🔑 в нике** -- права в этом канале есть. У ADM/MOD тега нет: у них права и так.\n' +
    '\n' +
    '🖥️ **Если бот выключен** -- напиши ';

// [v2.14] Текст помощи собирается НА СЕРВЕР: контакты в последней строке у разных
// экземпляров бота разные (см. contactsText). Тело -- одно на всех.
function helpText (server)
{
    return STARTUP_DM_TEXT + contactsText (server) + '.';
}

// [v2.6] Инструкция одним объектом -- чтобы /help, `panda help` и стартовая ЛС
// никогда не разъезжались по тексту:
function helpEmbed (server)
{
    const s = SERVERS[server];
    const first = server && s ? server : Object.keys (SERVERS)[0];
    return {
        color: 0x00CCFF,
        title: '🐼 PANDAMIA Bot: инструкция',
        description: helpText (first),
        footer:
        {
            text: (first && SERVERS[first]) ? SERVERS[first].name : 'PANDAMIA Bot',
        },
        timestamp: dt(), // [v14] только Date/number (locale-строка кидала 'Invalid time value'),
    };
}

const
{
    Client,
    GatewayIntentBits,
    Partials,
    ChannelType,
    PermissionsBitField,
    Collection,
    AuditLogEvent, // [v2.4] авторство действий: кто замутил/перенёс (из журнала аудита)
    ActivityType,  // [v2.8] профильный статус бота (слушает/смотрит/играет)
    ContextMenuCommandBuilder, // [v2.18] правый клик по сообщению -> «Переслать в общий»
    ApplicationCommandType,    // [v2.18] тип команды-контекстного меню (Message)
} = require ('discord.js');

// [v2.17] Guild Members ПОДКЛЮЧАЕМ (раньше он был убран по [v2.1]). Даёт мгновенные
// вход/выход вместо опроса раз в 45 сек. Резервный путь сохранён: если Discord интент
// не даёт, login упадёт 'Used disallowed intents' -- снимем интент и поедем как раньше
// (см. цикл входа ниже), а опрос участников остаётся включённым всегда.
const INTENTS =
[
    GatewayIntentBits.Guilds,
    GatewayIntentBits.GuildBans,
    GatewayIntentBits.GuildModeration, // [v2.4] журнал аудита: авторство мутов/переносов. НЕ привилегированный -- одобрения Discord не требует
    GatewayIntentBits.GuildMessages,
    // GatewayIntentBits.GuildPresences,
    GatewayIntentBits.GuildVoiceStates,
    GatewayIntentBits.DirectMessages,
];
if (USE_GUILD_MEMBERS)
    INTENTS.push (GatewayIntentBits.GuildMembers);
// [v2.5] ТЕКСТ сообщений: без этого интента Discord присылает события с пустым content
// (пересылка из пандалогии и команды 'panda ...' молчат). Интент привилегированный,
// но в портале приложения Peka он включён -- заявку подавать не надо (проверено).
if (USE_MESSAGE_CONTENT)
    INTENTS.push (GatewayIntentBits.MessageContent);

const client = new Client
(
    {
        intents: INTENTS,
        partials:
        [
            Partials.Channel, // DM-каналы не кэшируются без этого [v14]
        ],
    }
);

// ## DB!:
// keyv v5: именованный экспорт!
const { Keyv } = require ('keyv');
const { KeyvSqlite } = require ('@keyv/sqlite');

// [FIX v2.12.1] ВАЖНО: в keyv v5 конструктор со строкой-URI больше НЕ подгружает
// адаптер -- `new Keyv('sqlite://...')` молча уходит в стор по умолчанию (Map, т.е.
// ПАМЯТЬ). Все записи "как бы" работали (и даже читались обратно из того же
// экземпляра), но на диск не попадали: бан-таймауты не переживали перезапуск, а
// восстановление музыки было нечем восстанавливать. Проверено стендом:
//   store := Map (было)  ->  store := KeyvSqlite (стало)
// Теперь адаптер передаётся явным store-объектом, а namespace остаётся у Keyv --
// так ключи на диске остаются в прежнем виде ('membersBanTimeout:<id>'), то есть
// уже сохранённые баны читаются по-старому.
function dbMake (_server, _namespace)
{
    const kv = new Keyv
    ({
        store: new KeyvSqlite ({ uri: 'sqlite://' + __dirname + '/' + _server + '.sqlite' }),
        namespace: _namespace,
    });
    // Ошибки базы не должны теряться: раньше сбой записи был не виден вообще.
    kv.on ('error', e => console.error ('[db] ' + _namespace + ': ' + String ((e && e.message) || e).slice (0, 200)));
    return kv;
}

var $db = {};// ALL SERVERS!
for (let _server in SERVERS)
{
    $db[_server] = {};
    $db[_server]['membersBanTimeout'] = dbMake (_server, 'membersBanTimeout');
    $db[_server]['channelsBusy']      = dbMake (_server, 'channelsBusy');
    // [v2.10] очередь и позиция музыки -- чтобы перезапуск бота не сбрасывал плейлист:
    $db[_server]['musicState']        = dbMake (_server, 'musicState');
    // [v2.14] роли участников -- чтобы человек не терял их, выходя с сервера
    // (ключ -- id участника: возврат идёт именно по нему, см. restoreMemberRoles):
    $db[_server]['memberRoles']       = dbMake (_server, 'memberRoles');
    // [v2.15] история наказаний -- для отчёта «кто сколько раз выходил и попадал»
    // (ключ -- id участника, значение -- {at, events:[{at, kind}]}):
    $db[_server]['banHistory']        = dbMake (_server, 'banHistory');
}

async function db (server, namespace, id, value = undefined, item = undefined)
{
    if (id === '!!!WIPE!!!') // CLEAR ALL DB/SERVERS!
        return await $db[server][namespace].clear();
    else
        if (item === undefined) // no item
            if (value === undefined)
                return await $db[server][namespace].get (id);
            else // set value to -> id!
                if (value === null)
                    return await $db[server][namespace].delete (id);
                else
                    return await $db[server][namespace].set (id, value);
        else // item!
        {
            let obj = await $db[server][namespace].get (id);
            if (typeof obj !== 'object') obj = {}; // || {}!
            if (value === undefined)
                return obj[item];
            else
                if (value === null)
                {
                    delete obj[item]; // ->true
                    if (Object.keys(obj).length)
                        return await $db[server][namespace].set (id, obj);
                    else
                        return await $db[server][namespace].delete (id);
                }
                else
                {
                    obj[item] = value;
                    return await $db[server][namespace].set (id, obj);
                }
        }
}

// [FIX v2.2.1] страховка на уровне процесса: непойманное исключение/промис больше НЕ убивает бота
// (битые видео, сеть, прокси -- всё уходит в лог, бот продолжает работать):
process.on ('unhandledRejection', e => console.error ('[' + (d()) + '] [unhandledRejection] ' + String ((e && e.message) || e).slice (0, 300)));
process.on ('uncaughtException',  e => console.error ('[' + (d()) + '] [uncaughtException] '  + String ((e && e.message) || e).slice (0, 300)));

// [v2.5] Discord отдаёт текст сообщений только с интентом Message Content. Если он
// отзовёт доступ (заявка не одобрена до 09.10.2026) -- бот всё равно ЗАПУСТИТСЯ,
// просто без пересылки и команд 'panda ...'. Проверяем это заранее через REST и
// переподключаемся без интента, если Discord его не даёт ('Used disallowed intents').
async function messageContentAllowed ()
{
    try
    {
        const r = await fetch
        (
            'https://discord.com/api/v10/applications/@me',
            {headers: {Authorization: 'Bot ' + TOKEN}, signal: AbortSignal.timeout (5000)}
        );
        if (!r.ok) return true; // не смогли проверить -- пробуем с интентом (fallback ниже)
        const app = await r.json();
        // GATEWAY_MESSAGE_CONTENT (1<<18) / GATEWAY_MESSAGE_CONTENT_LIMITED (1<<19):
        return Boolean (app.flags & ((1 << 18) | (1 << 19)));
    }
    catch (e) { return true; }
}

// [v2.17] Человеческие имена интентов -- для строк в логе:
const INTENT_NAMES = new Map
([
    [GatewayIntentBits.GuildMembers, 'Guild Members (мгновенные вход/выход)'],
    [GatewayIntentBits.MessageContent, 'Message Content (текст сообщений и команды "panda ...")'],
]);

// Heavy GO! +D
// here you go...
(async () =>
{
    // Message Content можно проверить ЗАРАНЕЕ (флаги приложения), чтобы не тратить вход:
    if (USE_MESSAGE_CONTENT && !(await messageContentAllowed ()))
    {
        console.error ('[' + (d()) + '] [login] Message Content у приложения ОТКЛЮЧЁН -- запускаю без него' +
            ' (пересылка из пандалогии и команды "panda ..." работать не будут)');
        client.options.intents.remove (GatewayIntentBits.MessageContent);
    }
    if (!client.options.intents.has (GatewayIntentBits.MessageContent))
        console.log ('[' + (d()) + '] [login] без интента Message Content: текст сообщений недоступен');
    // [v2.17] Guild Members проверить заранее нечем -- узнаём по отказу Discord
    // ('Used disallowed intents', закрытие 4014). До двух отказов: снимаем по одному
    // привилегированному интенту и пробуем снова. Бот ОБЯЗАН запуститься в любом случае.
    const PRIVILEGED = [GatewayIntentBits.GuildMembers, GatewayIntentBits.MessageContent];
    for (let attempt = 0; attempt <= PRIVILEGED.length; attempt++)
    {
        try
        {
            await client.login (TOKEN);
            break;
        }
        catch (e)
        {
            const msg = String ((e && e.message) || e);
            const drop = /disallowed intent/i.test (msg) ? PRIVILEGED.find (i => client.options.intents.has (i)) : null;
            if (!drop)
            {
                console.error ('[login] error: ' + msg);
                break;
            }
            client.options.intents.remove (drop);
            const isMembers = drop === GatewayIntentBits.GuildMembers;
            console.error ('[' + (d()) + '] [login] Discord запретил интент ' + (INTENT_NAMES.get (drop) || 'привилегированный') +
                ' -- переподключаюсь без него (это не сбой бота: так работает откат)' +
                (isMembers
                    ? ' [вход/выход придётся ловить опросом -- а он требует тот же интент: без него приветствие, таймаут за выход и возврат ролей работать не будут]'
                    : ' [пересылка из пандалогии и команды "panda ..." работать не будут]'));
        }
    }
})();

